package com.yuyutian.mytools.catalog.service;
import com.yuyutian.mytools.catalog.model.CatalogModels.*;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import java.time.Instant;import java.util.List;import static org.assertj.core.api.Assertions.*;
/** 应用目录迁移测试。 */ @SpringBootTest class AppCatalogServiceTest {@Autowired private AppCatalogService service;
 @Test void shouldDryRunImportReplayAndReconcileLegacyAggregate(){LegacyAppImport dry=request(true,"catalog-v1");assertThat(service.importLegacy(dry).accepted()).isEqualTo(1);assertThat(service.list()).isEmpty();LegacyAppImport applied=request(false,"catalog-v1");assertThat(service.importLegacy(applied).accepted()).isEqualTo(1);assertThat(service.importLegacy(applied).skipped()).isEqualTo(1);assertThat(service.list()).singleElement().satisfies(value->{assertThat(value.legacyId()).isEqualTo("100");assertThat(value.versionCount()).isEqualTo(1);assertThat(value.fileCount()).isEqualTo(1);});Reconciliation reconciliation=service.reconciliation();assertThat(reconciliation.appCount()).isEqualTo(1);assertThat(reconciliation.versionCount()).isEqualTo(1);assertThat(reconciliation.fileCount()).isEqualTo(1);assertThat(reconciliation.unresolvedFileCount()).isEqualTo(1);assertThat(reconciliation.digestSha256()).hasSize(64);}
 @Test void shouldRejectMissingVersionRelationAndChangedReplay(){LegacyApp app=new LegacyApp("200",2,"Broken","app","1",null,null,null,null,"DRAFT",Instant.EPOCH,Instant.EPOCH);LegacyFile file=new LegacyFile("201","missing","binary","x","/legacy/x",1,Instant.EPOCH);assertThatThrownBy(()->service.importLegacy(new LegacyAppImport("catalog-v2",true,app,List.of(),List.of(file)))).isInstanceOf(IllegalArgumentException.class);LegacyAppImport original=request(false,"catalog-conflict");service.importLegacy(original);LegacyApp changed=new LegacyApp("100",1,"Changed","app","1.0",null,"content",null,null,"PUBLISHED",Instant.EPOCH,Instant.EPOCH);assertThat(service.importLegacy(new LegacyAppImport("catalog-conflict",false,changed,original.versions(),original.files())).rejected()).isEqualTo(1);}
 private LegacyAppImport request(boolean dryRun,String key){LegacyApp app=new LegacyApp("100",1,"Sample","app","1.0",null,"content",null,null,"PUBLISHED",Instant.EPOCH,Instant.EPOCH);LegacyVersion version=new LegacyVersion("110","1.0","content","120",Instant.EPOCH);LegacyFile file=new LegacyFile("120","110","binary","sample.zip","/legacy/sample.zip",12,Instant.EPOCH);return new LegacyAppImport(key,dryRun,app,List.of(version),List.of(file));}}
